        ET.SubElement(ET.SubElement(col, <span class="hljs-string">&quot;geometry&quot;</span>), <span class="hljs-string">&quot;cylinder&quot;</span>, radius=<span class="hljs-built_in">str</span>(r), length=<span class="hljs-built_in">str</span>(L))
        ine = ET.SubElement(l, <span class="hljs-string">&quot;inertial&quot;</span>); ET.SubElement(ine, <span class="hljs-string">&quot;origin&quot;</span>, xyz=<span class="hljs-string">f&quot;0 0 <span class="hljs-subst">{L / <span class="hljs-number">2</span>}</span>&quot;</span>, rpy=<span class="hljs-string">&quot;0 0 0&quot;</span>)
