        p = fk(text, q); a, b, c = q[<span class="hljs-string">&quot;joint2&quot;</span>], q[<span class="hljs-string">&quot;joint2&quot;</span>] + q[<span class="hljs-string">&quot;joint3&quot;</span>], q[<span class="hljs-string">&quot;joint1&quot;</span>]
        r = <span class="hljs-number">0.25</span> * np.sin(a) + <span class="hljs-number">0.15</span> * np.sin(b); z = <span class="hljs-number">0.05</span> + <span class="hljs-number">0.30</span> + <span class="hljs-number">0.25</span> * np.cos(a) + <span class="hljs-number">0.15</span> * np.cos(b)
